/** Groups whose names are all missing from `set`, deduplicated. */
export function unmetSecretAlternatives(groups, set) {
    const setNames = new Set(set ?? []);
    const seen = new Set();
    return groups.filter((group) => {
        const key = group.names.join("\n");
        if (seen.has(key) || group.names.some((name) => setNames.has(name))) {
            return false;
        }
        seen.add(key);
        return true;
    });
}
